{
  "schema": "threatline.threatmodel.v1",
  "issueKey": "EVAL-03",
  "sketch": {
    "components": ["Payment event publisher", "Kafka payment events topic", "Internal consumer services"],
    "dataStores": ["Kafka topic log", "Consumer-side datastores"],
    "externalServices": [],
    "trustBoundaries": ["Payment service to Kafka broker", "Kafka broker to any internal consumer service"],
    "dataClasses": ["payment", "pii"],
    "exposure": "internal",
    "llmFeatures": false
  },
  "threats": [
    {
      "stride": "InformationDisclosure",
      "title": "Every internal service can read card data from the payments topic",
      "scenario": "The design grants read access to all internal services, so any team or any compromised internal workload (a low-value reporting job, a dev-owned microservice) can subscribe and harvest card BIN, last four digits, amount and customer id for the entire payment stream. One foothold in any internal service yields bulk cardholder data for many customers with no further exploitation needed.",
      "component": "Kafka payment events topic",
      "likelihood": 4,
      "impact": 5,
      "evidence": [
        { "quote": "Payment events are published to a Kafka topic that every internal service can consume." }
      ],
      "asvs": ["V8.2.1"],
      "cwe": ["CWE-200", "CWE-285"],
      "plainLanguage": "Any internal system, not just the ones that need it, can read everyone's card details off the payment stream.",
      "requirement": {
        "title": "Restrict payment topic consumption to named services",
        "given": "a Kafka topic carrying payment events with card data",
        "when": "a service attempts to subscribe to the topic",
        "then": "the broker only allows consumer groups on an explicit allow-list of authorised services and denies all others"
      }
    },
    {
      "stride": "ElevationOfPrivilege",
      "title": "No topic-level authorisation means any workload can self-serve payment data or publish to it",
      "scenario": "Because consumption is open to 'every internal service', there is no per-principal ACL on the topic. An attacker who obtains any internal service credential, or a developer with cluster access, can create a consumer group or a producer client on the payment topic without approval, gaining payment-data privileges the service was never granted.",
      "component": "Kafka broker ACLs / authentication",
      "likelihood": 4,
      "impact": 4,
      "evidence": [
        { "quote": "Payment events are published to a Kafka topic that every internal service can consume." }
      ],
      "asvs": ["V8.2.1"],
      "cwe": ["CWE-306", "CWE-862"],
      "plainLanguage": "There is no gate on the stream, so anything inside the network can plug itself in as a reader or writer.",
      "requirement": {
        "title": "Authenticate and authorise every Kafka client",
        "given": "the payment events topic",
        "when": "a client connects to produce or consume",
        "then": "the broker requires a per-service authenticated identity (mTLS or SASL) and an explicit ACL grant for that identity and operation"
      }
    },
    {
      "stride": "Tampering",
      "title": "Forged or replayed payment events injected into the topic",
      "scenario": "With unrestricted access to the payment topic, an attacker inside the network can publish fabricated payment events, or replay captured ones, with chosen amount and customer id. Downstream consumers such as ledger, reconciliation or fraud services treat the stream as authoritative and will record payments that never happened or double-count real ones, causing financial loss and corrupt books.",
      "component": "Payment event producers",
      "likelihood": 3,
      "impact": 5,
      "evidence": [
        { "quote": "Events include the card BIN, last four digits, amount and customer id." }
      ],
      "asvs": [],
      "cwe": ["CWE-345", "CWE-294"],
      "plainLanguage": "Someone could post fake or repeated payment messages and downstream systems would believe them.",
      "requirement": {
        "title": "Verify authenticity and uniqueness of payment events",
        "given": "a consumer reading the payment events topic",
        "when": "an event arrives",
        "then": "the consumer rejects events whose producer identity is not the authorised payment service and ignores events whose unique event id has already been processed"
      }
    },
    {
      "stride": "InformationDisclosure",
      "title": "BIN plus last four plus customer id enables card and customer profiling",
      "scenario": "The event payload links a specific customer id to issuer, card type and last four digits plus transaction amounts. An attacker or curious insider with topic access can build per-customer spending profiles and use issuer and last-four details for convincing bank-impersonation phishing or call-centre takeover, even though no full PAN is present.",
      "component": "Payment event schema",
      "likelihood": 3,
      "impact": 4,
      "evidence": [
        { "quote": "Events include the card BIN, last four digits, amount and customer id." }
      ],
      "asvs": [],
      "cwe": ["CWE-359", "CWE-1230"],
      "plainLanguage": "The message includes more card and customer detail than consumers need, which is enough to impersonate a bank to the customer.",
      "requirement": {
        "title": "Minimise cardholder fields in the event payload",
        "given": "the payment event schema",
        "when": "an event is published to the shared topic",
        "then": "card BIN and last four digits are omitted or replaced by a non-reversible token, and consumers needing them fetch them from the payment service under separate authorisation"
      }
    },
    {
      "stride": "InformationDisclosure",
      "title": "Card data spreads into unmanaged consumer stores and log retention",
      "scenario": "Fan-out to every internal service means each consumer may persist or log the payment events in its own database, search index or application log, which are built for non-payment data and are not in the cardholder-data scope. The Kafka topic log itself also retains the card fields for its retention window. Sensitive data ends up copied to systems with weaker access control and no deletion path.",
      "component": "Consumer-side datastores and Kafka topic retention",
      "likelihood": 4,
      "impact": 4,
      "evidence": [
        { "quote": "Payment events are published to a Kafka topic that every internal service can consume." }
      ],
      "asvs": [],
      "cwe": ["CWE-532", "CWE-212"],
      "plainLanguage": "Once card data is on a shared stream, copies of it land in many databases and log files nobody is guarding.",
      "requirement": {
        "title": "Bound storage and retention of payment event data",
        "given": "payment events containing card fields",
        "when": "a consumer processes an event",
        "then": "card fields are not written to application logs or general-purpose stores, and the topic retention is limited to the shortest period the consumers need"
      }
    },
    {
      "stride": "Repudiation",
      "title": "No provenance on payment events so disputes cannot be settled",
      "scenario": "The design names no producer identity or signature on events. If a customer disputes a payment, or a bogus event is found in the ledger, there is no way to prove which service emitted it or whether it was altered in transit through the shared topic, so incidents cannot be attributed and fraudulent injection stays invisible.",
      "component": "Payment event schema / Kafka topic",
      "likelihood": 3,
      "impact": 3,
      "evidence": [
        { "quote": "Payment events are published to a Kafka topic that every internal service can consume." }
      ],
      "asvs": [],
      "cwe": ["CWE-778"],
      "plainLanguage": "Payment messages do not say who sent them, so you cannot prove where a wrong payment came from.",
      "requirement": {
        "title": "Attribute every payment event to its producer",
        "given": "a payment event on the topic",
        "when": "it is published",
        "then": "it carries an authenticated producer identity, an event id and a timestamp that consumers record, so any event can be traced to its origin"
      }
    }
  ]
}
